#include "tac.hpp"
namespace tac {
    CFG::CFG(const Function& function) {
        blocks.resize(1);
        instructions.resize(1);
        positions.resize(1);
        block_of.resize(1);
        std::vector<std::string> pending;
        int first_label = 0, current = 0;
        std::string previous;
        for (int index = 0;index < static_cast<int>(function.code.size());++index) {
            const Line& line = function.code[index];
            if (line.is_label()) {
                if (pending.empty()) first_label = index;
                pending.push_back(line.label);
                continue;
            }
            if (current == 0 || !pending.empty() || previous == "goto" || previous == "if" || previous == "return") {
                int start = pending.empty() ? index : first_label;
                if (current) blocks[current].end = start;
                Block block;
                block.start = start;
                block.labels = pending;
                blocks.push_back(block);
                pending.clear();
                current = static_cast<int>(blocks.size()) - 1;
            }
            int n = static_cast<int>(instructions.size());
            instructions.push_back(line.instruction);
            positions.push_back(index);
            block_of.push_back(current);
            blocks[current].instructions.push_back(n);
            previous = line.instruction.kind;
        }
        blocks[current].end = static_cast<int>(function.code.size());
        std::map<std::string, int> labels;
        for (int b = 1;b < static_cast<int>(blocks.size());++b) for (const std::string& label : blocks[b].labels) labels[label] = b;
        for (int b = 1;b < static_cast<int>(blocks.size());++b) {
            const Instruction& last = instructions[blocks[b].instructions.back()];
            if (last.kind == "goto") blocks[b].successors = {labels.at(last.name)};
            else if (last.kind == "if") {
                blocks[b].successors = {b + 1};
                int target = labels.at(last.name);
                if (target != b + 1) blocks[b].successors.push_back(target);
            } else if (last.kind != "return") blocks[b].successors = {b + 1};
            for (int s : blocks[b].successors) blocks[s].predecessors.push_back(b);
        }
        std::function<void(int)> visit =[&](int b) {
            reachable.insert(b);
            for (int s : blocks[b].successors) if (!reachable.count(s)) visit(s);
            postorder.push_back(b);
        };
        visit(1);
        reverse_postorder.assign(postorder.rbegin(), postorder.rend());
        for (int b : reachable) for (int p : blocks[b].predecessors) if (reachable.count(p)) blocks[b].reachable_predecessors.push_back(p);
        dominators.resize(blocks.size());
        immediate.assign(blocks.size(), 0);
        for (int b : reachable) dominators[b] = reachable;
        dominators[1] = {1};
        bool changed = true;
        while (changed) {
            changed = false;
            for (std::size_t i = 1;i < reverse_postorder.size();++i) {
                int b = reverse_postorder[i];
                const std::vector<int>& preds = blocks[b].reachable_predecessors;
                std::set<int> value = dominators[preds[0]];
                for (std::size_t j = 1;j < preds.size();++j) value = intersection(value, dominators[preds[j]]);
                value.insert(b);
                if (value != dominators[b]) {
                    dominators[b] = value;
                    changed = true;
                }
            }
        }
        for (int b : reachable) if (b != 1) {
            int best = 0;
            for (int d : dominators[b]) if (d != b &&(best == 0 || dominators[d].size() > dominators[best].size())) best = d;
            immediate[b] = best;
        }
        for (int header : reachable) {
            Loop loop;
            loop.header = header;
            for (int p : blocks[header].reachable_predecessors) if (dominators[p].count(header)) loop.latches.push_back(p);
            if (loop.latches.empty()) continue;
            loop.blocks.insert(header);
            std::vector<int> work;
            for (int latch : loop.latches) {
                loop.blocks.insert(latch);
                if (latch != header) work.push_back(latch);
            } while (!work.empty()) {
                int b = work.back();
                work.pop_back();
                for (int p : blocks[b].reachable_predecessors) if (loop.blocks.insert(p).second) work.push_back(p);
            }
            loops.push_back(loop);
        }
        for (Loop& loop : loops) {
            for (const Loop& other : loops) if (other.blocks.count(loop.header))++loop.depth;
            for (int b : loop.blocks) {
                ++blocks[b].depth;
                bool exit = instructions[blocks[b].instructions.back()].kind == "return";
                for (int s : blocks[b].successors) if (!loop.blocks.count(s)) {
                    loop.outside.insert(s);
                    exit = true;
                }
                if (exit) loop.exits.insert(b);
            }
        }
    }
}

#include "tac.hpp"
namespace tac {
    Definitions reaching_transfer(const Instruction& s, int n, Definitions state) {
        if (!s.destination.empty()) {
            for (Definitions::iterator it = state.begin();it != state.end();) if (it->first == s.destination) it = state.erase(it);
            else ++it;
            state.emplace(s.destination, n);
        }
        return state;
    }
    Variables live_transfer(const Instruction& s, Variables state) {
        state.erase(s.destination);
        for (const std::string& v : s.uses()) state.insert(v);
        return state;
    }
    Expressions expression_transfer(const Instruction& s, int, Expressions state) {
        std::optional<Expression> e = s.expression();
        if (e) state.insert(*e);
        for (Expressions::iterator it = state.begin();it != state.end();) {
            if ((s.kind == "store" && it->kind == "load" && it->operation == s.name) ||(s.kind == "call" && it->kind == "load") ||(!s.destination.empty() && it->uses(s.destination))) it = state.erase(it);
            else ++it;
        }
        return state;
    }
    Copies copy_transfer(const Instruction& s, int, Copies state) {
        if (!s.destination.empty()) for (Copies::iterator it = state.begin();it != state.end();) {
            if (it->first == s.destination || it->second == s.destination) it = state.erase(it);
            else ++it;
        }
        if (s.kind == "copy" && !s.a.constant && s.a.variable != s.destination) state.emplace(s.destination, s.a.variable);
        return state;
    }
    template<class T, class Transfer> static void forward(const Function& f, const CFG& g, const std::set<T>& universe, Transfer transfer, bool reaching, std::vector<std::set<T>>& in, std::vector<std::set<T>>& out, std::vector<std::set<T>>& before, int& iterations) {
        in.resize(g.blocks.size());
        out.resize(g.blocks.size());
        before.resize(g.instructions.size());
        for (int b : g.reachable) out[b] = universe;
        bool changed = true;
        while (changed) {
            changed = false;
            ++iterations;
            for (int b : g.reverse_postorder) {
                std::set<T> state;
                if (reaching) {
                    for (int p : g.blocks[b].reachable_predecessors) state.insert(out[p].begin(), out[p].end());
                    if constexpr (std::is_same<T, Definition>::value) if (b == 1) for (const std::string& p : f.parameters) state.emplace(p, 0);
                } else if (b != 1) {
                    const std::vector<int>& preds = g.blocks[b].reachable_predecessors;
                    state = out[preds[0]];
                    for (std::size_t i = 1;i < preds.size();++i) state = intersection(state, out[preds[i]]);
                }
                in[b] = state;
                for (int n : g.blocks[b].instructions) state = transfer(g.instructions[n], n, state);
                if (state != out[b]) {
                    out[b] = state;
                    changed = true;
                }
            }
        }
        for (int b : g.reachable) {
            std::set<T> state = in[b];
            for (int n : g.blocks[b].instructions) {
                before[n] = state;
                state = transfer(g.instructions[n], n, state);
            }
        }
    }
    DataFlow::DataFlow(const Function& f, const CFG& g) {
        Expressions expressions;
        Copies copies;
        for (std::size_t n = 1;n < g.instructions.size();++n) if (g.reachable.count(g.block_of[n])) {
            const Instruction& s = g.instructions[n];
            std::optional<Expression> e = s.expression();
            if (e) expressions.insert(*e);
            if (s.kind == "copy" && !s.a.constant && s.destination != s.a.variable) copies.emplace(s.destination, s.a.variable);
        }
        forward(f, g, Definitions {}, reaching_transfer, true, reaching_in, reaching_out, reaching_before, reaching_iterations);
        forward(f, g, expressions, expression_transfer, false, expression_in, expression_out, expression_before, expression_iterations);
        forward(f, g, copies, copy_transfer, false, copy_in, copy_out, copy_before, copy_iterations);
        live_in.resize(g.blocks.size());
        live_out.resize(g.blocks.size());
        live_before.resize(g.instructions.size());
        live_after.resize(g.instructions.size());
        bool changed = true;
        while (changed) {
            changed = false;
            ++live_iterations;
            for (int b : g.postorder) {
                Variables state;
                for (int s : g.blocks[b].successors) state.insert(live_in[s].begin(), live_in[s].end());
                live_out[b] = state;
                const std::vector<int>& ns = g.blocks[b].instructions;
                for (std::vector<int>::const_reverse_iterator it = ns.rbegin();it != ns.rend();++it) state = live_transfer(g.instructions[*it], state);
                if (state != live_in[b]) {
                    live_in[b] = state;
                    changed = true;
                }
            }
        }
        for (int b : g.reachable) {
            Variables state = live_out[b];
            const std::vector<int>& ns = g.blocks[b].instructions;
            for (std::vector<int>::const_reverse_iterator it = ns.rbegin();it != ns.rend();++it) {
                live_after[*it] = state;
                state = live_transfer(g.instructions[*it], state);
                live_before[*it] = state;
            }
        }
    }
}

#include "tac.hpp"
namespace tac {
    static std::set<int> reaching_numbers(const DataFlow& flow, int n, const std::string& v) {
        std::set<int> result;
        for (const Definition& d : flow.reaching_before[n]) if (d.first == v) result.insert(d.second);
        return result;
    }
    static std::optional<Integer> constant(const CFG& g, const std::set<int>& definitions) {
        if (definitions.empty() || definitions.count(0)) return std::nullopt;
        std::optional<Integer> result;
        for (int n : definitions) {
            const Instruction& s = g.instructions[n];
            if (s.kind != "copy" || !s.a.constant ||(result && *result != s.a.number)) return std::nullopt;
            result = s.a.number;
        }
        return result;
    }
    struct PassResult {
        int changes = 0;
        std::vector<std::string> records;
    };
    static PassResult propagation(Function& f, const CFG& g, const DataFlow& flow, bool constants) {
        PassResult result;
        Replacements edits;
        for (std::size_t n = 1;n < g.instructions.size();++n) if (g.reachable.count(g.block_of[n])) {
            Instruction s = g.instructions[n];
            for (Operand* operand : s.operands()) if (!operand->constant) {
                std::string variable = operand->variable;
                std::optional<Operand> replacement;
                if (constants) {
                    std::optional<Integer> c = constant(g, reaching_numbers(flow, static_cast<int>(n), variable));
                    if (c) replacement = Operand::value(*c);
                } else for (const Copy& pair : flow.copy_before[n]) if (pair.first == variable) {
                    replacement = Operand::parse(pair.second);
                    break;
                }
                if (replacement) {
                    result.records.push_back("#" + std::to_string(n) + ": " + variable + " -> " + replacement->text());
                    * operand = *replacement;
                }
            }
            if (constants) {
                std::optional<Instruction> folded = fold(s);
                if (!folded) {
                    result.records.push_back("#" + std::to_string(n) + ": delete " + s.text());
                    edits[static_cast<int>(n)] = {};
                    continue;
                }
                if (folded->text() != s.text()) result.records.push_back("#" + std::to_string(n) + ": fold " + folded->text());
                s = *folded;
            }
            edits[static_cast<int>(n)] = {Line::code(s)};
        }
        rewrite(f, edits);
        result.changes = static_cast<int>(result.records.size());
        return result;
    }
    static std::set<int> expression_sources(const CFG& g, const Expression& e, int candidate) {
        int b = g.block_of[candidate];
        std::set<int> sources, seen;
        const std::vector<int>& ns = g.blocks[b].instructions;
        for (std::vector<int>::const_reverse_iterator it = ns.rbegin();it != ns.rend();++it) if (*it < candidate && g.instructions[*it].expression() == std::optional<Expression>(e)) return {*it};
        std::vector<int> pending = g.blocks[b].reachable_predecessors;
        while (!pending.empty()) {
            int p = pending.back();
            pending.pop_back();
            if (!seen.insert(p).second) continue;
            bool found = false;
            const std::vector<int>& numbers = g.blocks[p].instructions;
            for (std::vector<int>::const_reverse_iterator it = numbers.rbegin();it != numbers.rend();++it) if (g.instructions[*it].expression() == std::optional<Expression>(e)) {
                sources.insert(*it);
                found = true;
                break;
            }
            if (!found) pending.insert(pending.end(), g.blocks[p].reachable_predecessors.begin(), g.blocks[p].reachable_predecessors.end());
        }
        return sources;
    }
    static PassResult cse(Function& f, const CFG& g, const DataFlow& flow) {
        std::map<Expression, std::vector<int>> groups;
        for (std::size_t n = 1;n < g.instructions.size();++n) if (g.reachable.count(g.block_of[n])) {
            std::optional<Expression> e = g.instructions[n].expression();
            if (e && flow.expression_before[n].count(*e)) groups[*e].push_back(static_cast<int>(n));
        }
        std::vector<std::pair<Expression, std::vector<int>>> ordered(groups.begin(), groups.end());
        std::sort(ordered.begin(), ordered.end(),[](const auto& a, const auto& b) {
            return a.second[0] < b.second[0];
        });
        PassResult result;
        Replacements edits;
        for (const std::pair<Expression, std::vector<int>>& group : ordered) {
            std::set<int> sources;
            for (int n : group.second) {
                std::set<int> found = expression_sources(g, group.first, n);
                sources.insert(found.begin(), found.end());
            }
            for (int n : group.second) sources.erase(n);
            std::string temporary = "_t" + std::to_string(++f.temporary_serial);
            for (int n : sources) {
                Instruction s = g.instructions[n], copy;
                copy.kind = "copy";
                copy.destination = s.destination;
                copy.a = Operand::parse(temporary);
                s.destination = temporary;
                edits[n] = {Line::code(s), Line::code(copy)};
            }
            for (int n : group.second) {
                Instruction s;
                s.kind = "copy";
                s.destination = g.instructions[n].destination;
                s.a = Operand::parse(temporary);
                edits[n] = {Line::code(s)};
            }
            result.changes += static_cast<int>(group.second.size());
            result.records.push_back(group.first.text() + ": " + temporary + " sources=" + numbers(sources, "#") + " replaced=" + numbers(group.second, "#"));
        }
        rewrite(f, edits);
        return result;
    }
    static PassResult dce(Function& f, const CFG& g, const DataFlow& flow) {
        Replacements edits;
        std::map<int, std::string> records;
        for (int b : g.reachable) {
            Variables state = flow.live_out[b];
            const std::vector<int>& ns = g.blocks[b].instructions;
            for (std::vector<int>::const_reverse_iterator it = ns.rbegin();it != ns.rend();++it) {
                int n = *it;
                Instruction s = g.instructions[n];
                if ((s.kind == "copy" && !s.a.constant && s.destination == s.a.variable) ||((s.kind == "copy" || s.kind == "bin" || s.kind == "load") && !state.count(s.destination))) {
                    edits[n] = {};
                    records[n] = "#" + std::to_string(n) + ": delete " + s.text();
                    continue;
                }
                if (s.kind == "call" && !s.destination.empty() && !state.count(s.destination)) {
                    records[n] = "#" + std::to_string(n) + ": unused result " + s.text();
                    s.destination.clear();
                    edits[n] = {Line::code(s)};
                }
                state = live_transfer(s, state);
            }
        }
        rewrite(f, edits);
        PassResult result;
        for (const std::pair<const int, std::string>& record : records) result.records.push_back(record.second);
        result.changes = static_cast<int>(result.records.size());
        return result;
    }
    static std::set<int> inside(const CFG& g, const Loop& loop, const std::set<int>& definitions) {
        std::set<int> result;
        for (int n : definitions) if (n && loop.blocks.count(g.block_of[n])) result.insert(n);
        return result;
    }
    static PassResult licm(Function& f, const CFG& g, const DataFlow& flow) {
        std::vector<Loop> loops = g.loops;
        std::sort(loops.begin(), loops.end(),[](const Loop& a, const Loop& b) {
            return a.blocks.size() != b.blocks.size() ? a.blocks.size() < b.blocks.size() : a.header < b.header;
        });
        for (const Loop& loop : loops) {
            std::vector<int> ns;
            std::set<std::string> stores;
            bool calls = false;
            for (int b : loop.blocks) for (int n : g.blocks[b].instructions) {
                ns.push_back(n);
                if (g.instructions[n].kind == "store") stores.insert(g.instructions[n].name);
                if (g.instructions[n].kind == "call") calls = true;
            }
            std::sort(ns.begin(), ns.end());
            std::set<int> marked;
            std::vector<int> order;
            bool changed = true;
            while (changed) {
                changed = false;
                for (int n : ns) {
                    const Instruction& s = g.instructions[n];
                    if (marked.count(n) ||(s.kind != "copy" && s.kind != "bin" && s.kind != "load") ||(s.kind == "load" &&(calls || stores.count(s.name)))) continue;
                    bool invariant = true;
                    for (const std::string& v : s.uses()) {
                        std::set<int> ds = reaching_numbers(flow, n, v), local = inside(g, loop, ds);
                        if (!local.empty() && !(ds.size() == 1 && marked.count(*local.begin()))) invariant = false;
                    }
                    if (invariant) {
                        marked.insert(n);
                        order.push_back(n);
                        changed = true;
                    }
                }
            }
            std::map<std::string, int> definition_counts;
            for (int n : ns) if (!g.instructions[n].destination.empty())++definition_counts[g.instructions[n].destination];
            std::vector<int> moves;
            std::set<int> moved;
            for (int n : order) {
                const Instruction& s = g.instructions[n];
                const std::string& x = s.destination;
                if (definition_counts[x] != 1 || flow.live_in[loop.header].count(x)) continue;
                bool dominates = true, dead = true;
                for (int exit : loop.exits) if (!g.dominators[exit].count(g.block_of[n])) dominates = false;
                for (int outside : loop.outside) if (flow.live_in[outside].count(x)) dead = false;
                bool dangerous = s.kind == "load" ||(s.kind == "bin" &&(s.operation == "/" || s.operation == "%") &&(!s.b.constant || s.b.number == 0));
                if (!dominates &&(dangerous || !dead)) continue;
                bool ready = true;
                for (const std::string& v : s.uses()) for (int d : inside(g, loop, reaching_numbers(flow, n, v))) if (!moved.count(d)) ready = false;
                if (ready) {
                    moves.push_back(n);
                    moved.insert(n);
                }
            }
            if (!moves.empty()) {
                std::string destination = hoist(f, g, loop, moves);
                return {static_cast<int>(moves.size()), {"B" + std::to_string(loop.header) + ": hoist " + numbers(moves, "#") + " to " + destination} };
            }
        }
        return {};
    }
    static PassResult apply(Function& f, const std::string& pass) {
        CFG graph(f);
        DataFlow flow(f, graph);
        if (pass == "constprop" || pass == "copyprop") return propagation(f, graph, flow, pass == "constprop");
        if (pass == "cse") return cse(f, graph, flow);
        if (pass == "dce") return dce(f, graph, flow);
        if (pass == "licm") return licm(f, graph, flow);
        PassResult result;
        result.records = remove_unreachable(f, graph);
        result.changes = static_cast<int>(result.records.size());
        return result;
    }
    struct CallGraph {
        std::map<std::string, std::vector<std::string>> callees;
        Variables reached, recursive;
        explicit CallGraph(const Program& p) {
            for (const Function& f : p.functions) {
                Variables called;
                for (const Line& l : f.code) if (!l.is_label() && l.instruction.kind == "call") called.insert(l.instruction.name);
                for (const Function& target : p.functions) if (called.count(target.name)) callees[f.name].push_back(target.name);
                callees[f.name];
            }
            std::function<Variables(std::vector<std::string>)> closure =[&](std::vector<std::string> pending) {
                Variables result;
                while (!pending.empty()) {
                    std::string name = pending.back();
                    pending.pop_back();
                    if (result.insert(name).second) pending.insert(pending.end(), callees[name].begin(), callees[name].end());
                }
                return result;
            };
            reached = closure({"main"});
            for (const Function& f : p.functions) if (closure(callees[f.name]).count(f.name)) recursive.insert(f.name);
        }
    };
    static void graph_report(std::vector<std::string>& out, const Program& p, const std::string& heading) {
        CallGraph g(p);
        out.push_back("== call graph (" + heading + ") ==");
        std::vector<std::string> missing;
        for (const Function& f : p.functions) {
            out.push_back(f.name + " -> " + join(g.callees[f.name]) +(g.recursive.count(f.name) ? " (recursive)" : ""));
            if (!g.reached.count(f.name)) missing.push_back(f.name);
        }
        out.push_back("unreachable functions: " + join(missing));
    }
    static std::string variables_text(const Variables& values) {
        return join(std::vector<std::string>(values.begin(), values.end()));
    }
    static std::string definitions_text(const Definitions& state) {
        std::vector<Definition> sorted(state.begin(), state.end());
        std::sort(sorted.begin(), sorted.end(),[](const Definition& a, const Definition& b) {
            return std::tie(a.second, a.first) < std::tie(b.second, b.first);
        });
        std::vector<std::string> result;
        for (const Definition& d : sorted) result.push_back(d.first + ":" + std::to_string(d.second));
        return join(result);
    }
    static std::string expressions_text(const Expressions& state) {
        Variables strings;
        for (const Expression& e : state) strings.insert(e.text());
        return variables_text(strings);
    }
    static void analysis_report(std::vector<std::string>& out, const Function& f, const std::string& heading) {
        CFG g(f);
        DataFlow flow(f, g);
        out.push_back("== " + f.name + " (" + heading + ") ==");
        out.push_back("code:");
        int n = 0;
        for (const Line& l : f.code) {
            if (l.is_label()) {
                out.push_back(l.label + ":");
                continue;
            }
            ++n;
            std::string text = "  #" + std::to_string(n) + " " + l.instruction.text();
            std::vector<std::string> chains;
            Variables seen;
            if (g.reachable.count(g.block_of[n])) for (const std::string& v : l.instruction.uses()) if (seen.insert(v).second) chains.push_back(v + ":" + numbers(reaching_numbers(flow, n, v)));
            if (!chains.empty()) text += " | " + join(chains, " ");
            out.push_back(text);
        }
        out.push_back("blocks: " + std::to_string(g.blocks.size() - 1));
        std::vector<int> unreachable;
        for (int b = 1;b < static_cast<int>(g.blocks.size());++b) {
            const Block& block = g.blocks[b];
            out.push_back("B" + std::to_string(b) + " " + std::to_string(block.instructions.front()) + "-" + std::to_string(block.instructions.back()) + " labels=" + join(block.labels) + " preds=" + numbers(block.predecessors, "B") + " succs=" + numbers(block.successors, "B"));
            if (!g.reachable.count(b)) unreachable.push_back(b);
        }
        out.push_back("unreachable: " + numbers(unreachable, "B"));
        out.push_back("order: " + numbers(g.reverse_postorder, "B"));
        out.push_back("dominators:");
        for (int b : g.reachable) out.push_back("B" + std::to_string(b) + " idom=" +(g.immediate[b] ? "B" + std::to_string(g.immediate[b]) : "-") + " dom=" + numbers(g.dominators[b], "B"));
        out.push_back("dominator tree:");
        std::function<void(int, int)> tree =[&](int b, int depth) {
            out.push_back(std::string(depth * 2, ' ') + "B" + std::to_string(b));
            for (int child : g.reachable) if (g.immediate[child] == b) tree(child, depth + 1);
        };
        tree(1, 0);
        out.push_back("loops: " + std::to_string(g.loops.size()));
        for (const Loop& loop : g.loops) out.push_back("header=B" + std::to_string(loop.header) + " latches=" + numbers(loop.latches, "B") + " depth=" + std::to_string(loop.depth) + " blocks=" + numbers(loop.blocks, "B") + " exits=" + numbers(loop.exits, "B"));
        out.push_back("reaching definitions: iterations=" + std::to_string(flow.reaching_iterations));
        for (int b : g.reachable) out.push_back("B" + std::to_string(b) + " in=" + definitions_text(flow.reaching_in[b]) + " out=" + definitions_text(flow.reaching_out[b]));
        out.push_back("liveness: iterations=" + std::to_string(flow.live_iterations));
        for (int b : g.reachable) out.push_back("B" + std::to_string(b) + " in=" + variables_text(flow.live_in[b]) + " out=" + variables_text(flow.live_out[b]));
        out.push_back("available expressions: iterations=" + std::to_string(flow.expression_iterations));
        for (int b : g.reachable) out.push_back("B" + std::to_string(b) + " in=" + expressions_text(flow.expression_in[b]) + " out=" + expressions_text(flow.expression_out[b]));
    }
    static Function allocation_report(std::vector<std::string>& out, const Function& f, int registers) {
        CFG graph(f);
        DataFlow flow(f, graph);
        Allocation allocation(f, graph, flow, registers);
        Function allocated = f;
        allocated.code.clear();
        int moves = 0, edges = 0, pressure = 0, spill_uses = 0, spill_defs = 0;
        std::set<int> used;
        std::function<std::string(const std::string&)> rename =[&](const std::string& name) {
            std::map<std::string, int>::const_iterator it = allocation.colors.find(name);
            return it != allocation.colors.end() && it->second >= 0 ? "R" + std::to_string(it->second) : name;
        };
        for (std::string& p : allocated.parameters) p = rename(p);
        for (const Line& line : f.code) {
            if (line.is_label()) {
                allocated.code.push_back(line);
                continue;
            }
            Instruction s = line.instruction;
            if (!s.destination.empty()) s.destination = rename(s.destination);
            for (Operand* o : s.operands()) if (!o->constant) o->variable = rename(o->variable);
            if (s.kind == "copy" && !s.a.constant && s.destination == s.a.variable)++moves;
            else allocated.code.push_back(Line::code(s));
            for (const std::string& v : line.instruction.uses()) spill_uses += allocation.spills.count(v);
            spill_defs += allocation.spills.count(line.instruction.destination);
        }
        for (const std::string& p : f.parameters) spill_defs += allocation.spills.count(p);
        for (const Variables& state : flow.live_before) pressure = std::max(pressure, static_cast<int>(state.size()));
        for (const Variables& state : flow.live_after) pressure = std::max(pressure, static_cast<int>(state.size()));
        for (const auto& entry : allocation.neighbors) edges += static_cast<int>(entry.second.size());
        out.push_back("== " + f.name + " ==");
        out.push_back("nodes=" + std::to_string(allocation.neighbors.size()) + " edges=" + std::to_string(edges/2) + " registers=" + std::to_string(registers));
        for (const auto& entry : allocation.neighbors) out.push_back(entry.first + " degree=" + std::to_string(entry.second.size()) + " cost=" + allocation.costs[entry.first].text() + " neighbors=" + variables_text(entry.second));
        out.push_back("simplify: " + join(allocation.order));
        std::vector<std::string> potential;
        for (const std::pair<std::string, int>& p : allocation.potential) potential.push_back(p.first + "(" + allocation.costs[p.first].text() + "/" + std::to_string(p.second) + ")");
        out.push_back("potential spills: " + join(potential));
        for (const std::pair<const std::string, int>& p : allocation.colors) {
            out.push_back(p.first + " -> " +(p.second < 0 ? "spill" : "R" + std::to_string(p.second)));
            if (p.second >= 0) used.insert(p.second);
        }
        out.push_back("summary: pressure=" + std::to_string(pressure) + " used=" + std::to_string(used.size()) + " spilled=" + std::to_string(allocation.spills.size()) + " moves=" + std::to_string(moves) + " spill_uses=" + std::to_string(spill_uses) + " spill_defs=" + std::to_string(spill_defs));
        std::vector<std::string> lines = function_lines(allocated);
        out.insert(out.end(), lines.begin(), lines.end());
        return allocated;
    }
    struct Execution {
        const Program& program;
        std::map<std::string, std::vector<Integer>> arrays;
        const std::vector<Integer>& inputs;
        std::size_t input_position = 0;
        std::vector<Integer> output;
        std::map<std::string, Integer> steps, calls, dynamic;
        Execution(const Program& p, const std::vector<Integer>& values) : program(p), inputs(values) {
            for (const auto& a : p.arrays) arrays[a.first].resize(a.second);
        }
        Integer call(const std::string& name, const std::vector<Integer>& args) {
            const Function* f = nullptr;
            for (const Function& candidate : program.functions) if (candidate.name == name) f = &candidate;
            std::map<std::string, Integer> vars;
            for (std::size_t i = 0;i < args.size();++i) vars[f->parameters[i]] = args[i];
            std::vector<Integer> pushed;
            std::map<std::string, int> labels;
            std::vector<Instruction> code;
            for (const Line& line : f->code) {
                if (line.is_label()) labels[line.label] = static_cast<int>(code.size());
                else code.push_back(line.instruction);
            }
            ++calls[name];
            int position = 0;
            std::function<Integer(const Operand&)> value =[&](const Operand& o) {
                return o.constant ? o.number : vars.at(o.variable);
            };
            while (true) {
                const Instruction& s = code[position++];
                ++steps[name];
                ++dynamic[s.kind];
                if (s.kind == "copy") vars[s.destination] = value(s.a);
                else if (s.kind == "bin") vars[s.destination] = calculate(s.operation, value(s.a), value(s.b));
                else if (s.kind == "load") vars[s.destination] = arrays.at(s.name).at(static_cast<std::size_t>(value(s.a)));
                else if (s.kind == "store") arrays.at(s.name).at(static_cast<std::size_t>(value(s.a))) = value(s.b);
                else if (s.kind == "goto") position = labels.at(s.name);
                else if (s.kind == "if") {
                    if (calculate(s.operation, value(s.a), value(s.b))) position = labels.at(s.name);
                } else if (s.kind == "param") pushed.push_back(value(s.a));
                else if (s.kind == "call") {
                    std::vector<Integer> arguments(pushed.end() - s.count, pushed.end());
                    pushed.erase(pushed.end() - s.count, pushed.end());
                    Integer result = call(s.name, arguments);
                    if (!s.destination.empty()) vars[s.destination] = result;
                } else if (s.kind == "return") return s.has_operand ? value(s.a) : 0;
                else if (s.kind == "read") vars[s.destination] = inputs.at(input_position++);
                else if (s.kind == "print") output.push_back(value(s.a));
            }
        }
    };
    static Integer sum(const std::map<std::string, Integer>& values) {
        Integer result = 0;
        for (const auto& entry : values) result += entry.second;
        return result;
    }
    static std::string integers(const std::vector<Integer>& values) {
        std::vector<std::string> strings;
        for (Integer v : values) strings.push_back(std::to_string(v));
        return join(strings);
    }
    static std::map<std::string, Integer> static_kinds(const Program& p) {
        std::map<std::string, Integer> counts;
        for (const Function& f : p.functions) for (const Line& l : f.code) if (!l.is_label())++counts[l.instruction.kind];
        return counts;
    }
    static std::vector<std::string> comparisons(const Program& original, const Program& optimized, const Program& allocated, const std::vector<std::vector<Integer>>& runs) {
        const std::array<const Program*, 3> programs = {&original, &optimized, &allocated};
        const std::array<std::string, 3> names = {"original", "optimized", "allocated"};
        std::array<std::map<std::string, Integer>, 3> profiles, dynamic;
        std::array<Integer, 3> total {};
        std::map<std::string, Integer> calls;
        int same = 0;
        std::vector<std::string> out;
        for (std::size_t i = 0;i < runs.size();++i) {
            out.push_back("run " + std::to_string(i + 1) + ": inputs=" + std::to_string(runs[i].size()));
            std::array<std::vector<Integer>, 3> results;
            for (int v = 0;v < 3;++v) {
                Execution execution(*programs[v], runs[i]);
                execution.call("main", {});
                Integer steps = sum(execution.steps);
                out.push_back("  " + names[v] + ": steps=" + std::to_string(steps) + " calls=" + std::to_string(sum(execution.calls)) + " output=" + integers(execution.output));
                results[v] = execution.output;
                total[v] += steps;
                for (const auto& entry : execution.steps) profiles[v][entry.first] += entry.second;
                for (const auto& entry : execution.dynamic) dynamic[v][entry.first] += entry.second;
                if (v == 0) for (const auto& entry : execution.calls) calls[entry.first] += entry.second;
            }
            bool equal = results[0] == results[1] && results[1] == results[2];
            same += equal;
            out.push_back(std::string("  result: ") +(equal ? "same" : "different"));
        }
        out.push_back("== profile ==");
        for (const Function& f : original.functions) out.push_back(f.name + ": calls=" + std::to_string(calls[f.name]) + " original=" + std::to_string(profiles[0][f.name]) + " optimized=" + std::to_string(profiles[1][f.name]) + " allocated=" + std::to_string(profiles[2][f.name]));
        std::map<std::string, Integer> a = static_kinds(original), b = static_kinds(optimized);
        out.push_back("== summary ==");
        out.push_back("runs=" + std::to_string(runs.size()) + " same=" + std::to_string(same) + " different=" + std::to_string(runs.size() - same));
        out.push_back("instructions: original=" + std::to_string(sum(a)) + " optimized=" + std::to_string(sum(b)));
        std::vector<std::string> counts;
        for (const std::string& kind : kinds) counts.push_back(kind + "=" + std::to_string(a[kind]) + "->" + std::to_string(b[kind]));
        out.push_back("kinds: " + join(counts, " "));
        out.push_back("steps: original=" + std::to_string(total[0]) + " optimized=" + std::to_string(total[1]) + " allocated=" + std::to_string(total[2]));
        for (int v = 0;v < 3;++v) {
            counts.clear();
            for (const std::string& kind : kinds) counts.push_back(kind + "=" + std::to_string(dynamic[v][kind]));
            out.push_back("dynamic " + names[v] + ": " + join(counts, " "));
        }
        return out;
    }
    static void write(const std::string& name, const std::vector<std::string>& lines) {
        std::ofstream out("output/" + name);
        for (const std::string& line : lines) out << line << '\n';
    }
}
int main() {
    using namespace tac;
    std::ifstream settings("input/params.txt");
    std::string word, line;
    int registers, max_rounds;
    settings >> word >> registers;
    std::getline(settings, line);
    std::getline(settings, line);
    std::istringstream passes_line(line);
    passes_line >> word;
    Variables enabled;
    while (passes_line >> word) enabled.insert(word);
    settings >> word >> max_rounds;
    std::vector<std::string> passes;
    for (const std::string& name : std::vector<std::string> {"constprop", "copyprop", "cse", "dce", "licm", "unreachable"}) if (enabled.count(name)) passes.push_back(name);
    std::ifstream input("input/input.txt");
    int count;
    input >> count;
    std::vector<std::vector<Integer>> runs;
    for (int i = 0;i < count;++i) {
        int n;
        input >> n;
        std::vector<Integer> values(n);
        for (Integer& value : values) input >> value;
        runs.push_back(values);
    }
    Program original = read_program("input/program.tac"), working = original;
    std::vector<std::string> analysis, pass_lines, allocation_lines;
    std::map<std::string, Integer> totals;
    graph_report(analysis, original, "original");
    for (const Function& f : original.functions) analysis_report(analysis, f, "original");
    for (Function& f : working.functions) {
        int before = f.instruction_count(), round = 0;
        pass_lines.push_back("== " + f.name + " ==");
        for (round = 1;round <= max_rounds;++round) {
            bool changed = false;
            std::vector<std::string> counts, records;
            for (const std::string& pass : passes) {
                PassResult result = apply(f, pass);
                changed = changed || result.changes != 0;
                totals[pass] += result.changes;
                counts.push_back(pass + "=" + std::to_string(result.changes));
                for (const std::string& record : result.records) records.push_back("  " + pass + " " + record);
            }
            pass_lines.push_back("round " + std::to_string(round) + ": " + join(counts, " "));
            pass_lines.insert(pass_lines.end(), records.begin(), records.end());
            if (!changed || round == max_rounds) break;
        }
        pass_lines.push_back("result: rounds=" + std::to_string(round) + " instructions=" + std::to_string(before) + "->" + std::to_string(f.instruction_count()));
    }
    graph_report(analysis, working, "optimized");
    CallGraph graph(working);
    Program optimized;
    optimized.arrays = working.arrays;
    std::vector<std::string> removed;
    for (const Function& f : working.functions) {
        if (enabled.count("unreachable") && !graph.reached.count(f.name)) removed.push_back(f.name);
        else optimized.functions.push_back(f);
    }
    pass_lines.insert(pass_lines.end(), {"== program ==", "removed functions: " + join(removed), "== total =="});
    std::vector<std::string> counts;
    for (const std::string& pass : passes) counts.push_back(pass + "=" + std::to_string(totals[pass]));
    pass_lines.push_back(join(counts, " "));
    Program allocated;
    allocated.arrays = optimized.arrays;
    for (const Function& f : optimized.functions) {
        analysis_report(analysis, f, "optimized");
        allocated.functions.push_back(allocation_report(allocation_lines, f, registers));
    }
    write("optimized.tac", program_lines(optimized));
    write("analysis.txt", analysis);
    write("passes.txt", pass_lines);
    write("regalloc.txt", allocation_lines);
    write("comparison.txt", comparisons(original, optimized, allocated, runs));
}

#include "tac.hpp"
namespace tac {
    void rewrite(Function& f, const Replacements& replacements, const std::map<int, std::vector<Line>>& insertions) {
        std::vector<Line> result;
        int n = 0;
        for (int i = 0;i <= static_cast<int>(f.code.size());++i) {
            std::map<int, std::vector<Line>>::const_iterator ins = insertions.find(i);
            if (ins != insertions.end()) result.insert(result.end(), ins->second.begin(), ins->second.end());
            if (i == static_cast<int>(f.code.size())) break;
            const Line& line = f.code[i];
            if (line.is_label()) result.push_back(line);
            else {
                ++n;
                Replacements::const_iterator edit = replacements.find(n);
                if (edit == replacements.end()) result.push_back(line);
                else result.insert(result.end(), edit->second.begin(), edit->second.end());
            }
        }
        f.code = std::move(result);
    }
    std::optional<Instruction> fold(const Instruction& s) {
        if (s.kind != "bin" && s.kind != "if") return s;
        if (s.a.constant && s.b.constant) {
            if ((s.operation == "/" || s.operation == "%") && s.b.number == 0) return s;
            Integer value = calculate(s.operation, s.a.number, s.b.number);
            if (s.kind == "if") {
                if (!value) return std::nullopt;
                Instruction result;
                result.kind = "goto";
                result.name = s.name;
                return result;
            }
            if (value < -2147483648LL || value > 2147483647LL) return s;
            Instruction result;
            result.kind = "copy";
            result.destination = s.destination;
            result.a = Operand::value(value);
            return result;
        }
        if (s.kind != "bin" || s.a.constant == s.b.constant) return s;
        std::optional<Operand> replacement;
        if (s.operation == "+" &&((s.a.constant && s.a.number == 0) ||(s.b.constant && s.b.number == 0))) replacement = s.a.constant ? s.b : s.a;
        else if (s.operation == "-" && s.b.constant && s.b.number == 0) replacement = s.a;
        else if (s.operation == "*" &&((s.a.constant && s.a.number == 1) ||(s.b.constant && s.b.number == 1))) replacement = s.a.constant ? s.b : s.a;
        else if (s.operation == "/" && s.b.constant && s.b.number == 1) replacement = s.a;
        else if (s.operation == "*" &&((s.a.constant && s.a.number == 0) ||(s.b.constant && s.b.number == 0))) replacement = Operand::value(0);
        if (!replacement) return s;
        Instruction result;
        result.kind = "copy";
        result.destination = s.destination;
        result.a = *replacement;
        return result;
    }
    std::string hoist(Function& f, const CFG& g, const Loop& loop, const std::vector<int>& moves) {
        const Block& header = g.blocks[loop.header];
        std::vector<int> outside;
        for (int p : header.predecessors) if (!loop.blocks.count(p)) outside.push_back(p);
        Replacements replacements;
        std::vector<Line> insertion;
        for (int n : moves) {
            replacements[n] = {};
            insertion.push_back(Line::code(g.instructions[n]));
        }
        int position;
        std::string destination;
        if (loop.header != 1 && outside.size() == 1 && g.blocks[outside[0]].successors == std::vector<int> {loop.header}) {
            const Block& preheader = g.blocks[outside[0]];
            int last = preheader.instructions.back();
            position = g.positions[last];
            if (g.instructions[last].kind != "goto" && g.instructions[last].kind != "if")++position;
            destination = "B" + std::to_string(outside[0]);
        } else {
            std::string label = "_p" + std::to_string(++f.preheader_serial);
            position = header.start;
            insertion.insert(insertion.begin(), Line::named(label));
            destination = "new " + label;
            for (int p : outside) {
                int n = g.blocks[p].instructions.back();
                Instruction s = g.instructions[n];
                if ((s.kind == "goto" || s.kind == "if") && std::find(header.labels.begin(), header.labels.end(), s.name) != header.labels.end()) {
                    s.name = label;
                    replacements[n] = {Line::code(s)};
                }
            }
        }
        rewrite(f, replacements, { {position, insertion} });
        return destination;
    }
    std::vector<std::string> remove_unreachable(Function& f, const CFG& g) {
        std::set<int> removed;
        std::vector<std::string> records;
        for (int b = 1;b < static_cast<int>(g.blocks.size());++b) if (!g.reachable.count(b)) {
            records.push_back("remove block B" + std::to_string(b));
            for (int i = g.blocks[b].start;i < g.blocks[b].end;++i) removed.insert(i);
        }
        std::vector<std::pair<Line, int>> remaining;
        int n = 0;
        for (int i = 0;i < static_cast<int>(f.code.size());++i) {
            if (!f.code[i].is_label())++n;
            if (!removed.count(i)) remaining.emplace_back(f.code[i], f.code[i].is_label() ? 0 : n);
        }
        std::set<int> jumps;
        for (std::size_t i = 0;i < remaining.size();++i) {
            const Line& line = remaining[i].first;
            if (line.is_label() ||(line.instruction.kind != "goto" && line.instruction.kind != "if")) continue;
            for (std::size_t j = i + 1;j < remaining.size() && remaining[j].first.is_label();++j) if (line.instruction.name == remaining[j].first.label) jumps.insert(remaining[i].second);
        }
        for (int number : jumps) records.push_back("remove jump #" + std::to_string(number));
        std::set<std::string> targets;
        for (const std::pair<Line, int>& entry : remaining) if (!entry.first.is_label() && !jumps.count(entry.second) &&(entry.first.instruction.kind == "goto" || entry.first.instruction.kind == "if")) targets.insert(entry.first.instruction.name);
        f.code.clear();
        for (const std::pair<Line, int>& entry : remaining) {
            const Line& line = entry.first;
            if (line.is_label() && !targets.count(line.label)) records.push_back("remove label " + line.label);
            else if (!jumps.count(entry.second)) f.code.push_back(line);
        }
        return records;
    }
}

#include "tac.hpp"
namespace tac {
    Cost Cost::power(int exponent) {
        Cost value;
        value.digits = "1" + std::string(exponent, '0');
        return value;
    }
    Cost& Cost::operator +=(const Cost& other) {
        std::string a = digits, b = other.digits, result;
        std::reverse(a.begin(), a.end());
        std::reverse(b.begin(), b.end());
        int carry = 0;
        for (std::size_t i = 0;i < std::max(a.size(), b.size()) || carry;++i) {
            int sum = carry +(i < a.size() ? a[i] - '0' : 0) +(i < b.size() ? b[i] - '0' : 0);
            result.push_back(static_cast<char>('0' + sum%10));
            carry = sum/10;
        }
        if (result.empty()) result = "0";
        std::reverse(result.begin(), result.end());
        digits = result;
        return *this;
    }
    Cost Cost::times(int factor) const {Cost result;
    std::string reversed;
    int carry = 0;
    for (std::string::const_reverse_iterator it = digits.rbegin();it != digits.rend();++it) {
        int v =(*it - '0') * factor + carry;
        reversed.push_back(static_cast<char>('0' + v%10));
        carry = v/10;
    } while (carry) {
        reversed.push_back(static_cast<char>('0' + carry%10));
        carry /= 10;
    } while (reversed.size() > 1 && reversed.back() == '0') reversed.pop_back();
    std::reverse(reversed.begin(), reversed.end());
    result.digits = reversed;
    return result;
    } bool Cost::operator <(const Cost& other) const {return digits.size() != other.digits.size() ? digits.size() < other.digits.size() : digits < other.digits;
    } Allocation::Allocation(const Function& f, const CFG& g, const DataFlow& flow, int registers) {
        Variables nodes(f.parameters.begin(), f.parameters.end());
        for (std::size_t n = 1;n < g.instructions.size();++n) if (g.reachable.count(g.block_of[n])) {
            const Instruction& s = g.instructions[n];
            for (const std::string& v : s.uses()) nodes.insert(v);
            if (!s.destination.empty()) nodes.insert(s.destination);
        }
        for (const std::string& v : nodes) {
            neighbors[v];
            partners[v];
            costs[v];
        }
        std::function<void(const std::string&, const std::string&)> edge =[&](const std::string& a, const std::string& b) {
            if (a != b) {
                neighbors[a].insert(b);
                neighbors[b].insert(a);
            }
        };
        for (int b : g.reachable) {
            Variables state = flow.live_out[b];
            const std::vector<int>& ns = g.blocks[b].instructions;
            for (std::vector<int>::const_reverse_iterator it = ns.rbegin();it != ns.rend();++it) {
                const Instruction& s = g.instructions[*it];
                if (!s.destination.empty()) for (const std::string& v : state) if (v != s.destination && !(s.kind == "copy" && !s.a.constant && v == s.a.variable)) edge(s.destination, v);
                state = live_transfer(s, state);
            }
            Cost weight = Cost::power(g.blocks[b].depth);
            for (int n : ns) {
                const Instruction& s = g.instructions[n];
                for (const std::string& v : s.uses()) costs[v] += weight;
                if (!s.destination.empty()) costs[s.destination] += weight;
            }
        }
        Variables entry = flow.live_in[1];
        entry.insert(f.parameters.begin(), f.parameters.end());
        for (const std::string& p : f.parameters) {
            costs[p] += Cost::power(0);
            for (const std::string& v : entry) edge(p, v);
        }
        for (const Line& line : f.code) if (!line.is_label()) {
            const Instruction& s = line.instruction;
            if (s.kind == "copy" && !s.a.constant && s.destination != s.a.variable) {
                if (nodes.count(s.destination)) partners[s.destination].insert(s.a.variable);
                if (nodes.count(s.a.variable)) partners[s.a.variable].insert(s.destination);
            }
        }
        Variables remaining = nodes;
        while (!remaining.empty()) {
            std::map<std::string, int> degrees;
            std::string chosen;
            int degree = 0;
            bool simple = false;
            for (const std::string& v : remaining) degrees[v] = static_cast<int>(intersection(neighbors[v], remaining).size());
            for (const std::string& v : remaining) if (degrees[v] < registers &&(!simple || degrees[v] < degree)) {
                simple = true;
                chosen = v;
                degree = degrees[v];
            }
            if (!simple) {
                for (const std::string& v : remaining) if (chosen.empty() || costs[v].times(degrees[chosen]) < costs[chosen].times(degrees[v])) chosen = v;
                degree = degrees[chosen];
                potential.emplace_back(chosen, degree);
            }
            order.push_back(chosen);
            remaining.erase(chosen);
        }
        for (std::vector<std::string>::const_reverse_iterator it = order.rbegin();it != order.rend();++it) {
            const std::string& v = *it;
            std::set<int> free;
            for (int r = 0;r < registers;++r) free.insert(r);
            for (const std::string& n : neighbors[v]) if (colors.count(n) && colors[n] >= 0) free.erase(colors[n]);
            if (free.empty()) {
                colors[v] = -1;
                spills.insert(v);
                continue;
            }
            std::set<int> preferred;
            for (const std::string& p : partners[v]) if (colors.count(p) && free.count(colors[p])) preferred.insert(colors[p]);
            colors[v] = preferred.empty() ? *free.begin() : *preferred.begin();
        }
    }
}

#ifndef TAC_HPP
#define TAC_HPP
#include <algorithm>
#include <array>
#include <cstdint>
#include <fstream>
#include <functional>
#include <iterator>
#include <map>
#include <numeric>
#include <optional>
#include <set>
#include <sstream>
#include <string>
#include <tuple>
#include <type_traits>
#include <utility>
#include <vector>
namespace tac {
    using Integer = std::int64_t;
    struct Operand {
        bool constant = false;
        Integer number = 0;
        std::string variable;
        static Operand parse(const std::string& word);
        static Operand value(Integer number);
        std::string text() const;
        bool operator <(const Operand& other) const;
        bool operator ==(const Operand& other) const;
    };
    struct Expression {
        std::string kind, operation;
        Operand a, b;
        bool operator <(const Expression& other) const;
        bool operator ==(const Expression& other) const;
        std::string text() const;
        bool uses(const std::string& variable) const;
    };
    struct Instruction {
        std::string kind, destination, operation, name;
        Operand a, b;
        bool has_operand = false;
        int count = 0;
        std::vector<Operand*> operands();
        std::vector<Operand> operands() const;
        std::vector<std::string> uses() const;
        std::optional<Expression> expression() const;
        std::string text() const;
    };
    struct Line {
        std::string label;
        Instruction instruction;
        bool is_label() const {return !label.empty();
        } static Line named(const std::string& name) {
            Line line;
            line.label = name;
            return line;
        }
        static Line code(const Instruction& value) {
            Line line;
            line.instruction = value;
            return line;
        }
    };
    struct Function {
        std::string name;
        std::vector<std::string> parameters;
        std::vector<Line> code;
        int temporary_serial = 0, preheader_serial = 0;
        int instruction_count() const;
    };
    struct Program {
        std::vector<std::pair<std::string, int>> arrays;
        std::vector<Function> functions;
    };
    extern const std::vector<std::string> kinds;
    Program read_program(const std::string& path);
    std::vector<std::string> function_lines(const Function& function);
    std::vector<std::string> program_lines(const Program& program);
    Integer calculate(const std::string& operation, Integer a, Integer b);
    std::string join(const std::vector<std::string>& values, const std::string& separator = ",", const std::string& empty = "-");
    std::string numbers(const std::vector<int>& values, const std::string& prefix = "");
    std::string numbers(const std::set<int>& values, const std::string& prefix = "");
    template<class T> std::set<T> intersection(const std::set<T>& a, const std::set<T>& b) {
        std::set<T> result;
        std::set_intersection(a.begin(), a.end(), b.begin(), b.end(), std::inserter(result, result.end()));
        return result;
    }
    struct Block {
        int start = 0, end = 0, depth = 0;
        std::vector<std::string> labels;
        std::vector<int> instructions, predecessors, successors, reachable_predecessors;
    };
    struct Loop {
        int header = 0, depth = 0;
        std::vector<int> latches;
        std::set<int> blocks, exits, outside;
    };
    struct CFG {
        std::vector<Block> blocks;
        std::vector<Instruction> instructions;
        std::vector<int> positions, block_of, postorder, reverse_postorder, immediate;
        std::set<int> reachable;
        std::vector<std::set<int>> dominators;
        std::vector<Loop> loops;
        explicit CFG(const Function& function);
    };
    using Definition = std::pair<std::string, int>;
    using Copy = std::pair<std::string, std::string>;
    using Definitions = std::set<Definition>;
    using Variables = std::set<std::string>;
    using Expressions = std::set<Expression>;
    using Copies = std::set<Copy>;
    Definitions reaching_transfer(const Instruction& instruction, int number, Definitions state);
    Variables live_transfer(const Instruction& instruction, Variables state);
    Expressions expression_transfer(const Instruction& instruction, int number, Expressions state);
    Copies copy_transfer(const Instruction& instruction, int number, Copies state);
    struct DataFlow {
        std::vector<Definitions> reaching_in, reaching_out, reaching_before;
        std::vector<Variables> live_in, live_out, live_before, live_after;
        std::vector<Expressions> expression_in, expression_out, expression_before;
        std::vector<Copies> copy_in, copy_out, copy_before;
        int reaching_iterations = 0, live_iterations = 0, expression_iterations = 0, copy_iterations = 0;
        DataFlow(const Function& function, const CFG& graph);
    };
    using Replacements = std::map<int, std::vector<Line>>;
    void rewrite(Function& function, const Replacements& replacements, const std::map<int, std::vector<Line>>& insertions = {});
    std::optional<Instruction> fold(const Instruction& instruction);
    std::string hoist(Function& function, const CFG& graph, const Loop& loop, const std::vector<int>& moves);
    std::vector<std::string> remove_unreachable(Function& function, const CFG& graph);
    class Cost {
        std::string digits = "0";
        public:
        static Cost power(int exponent);
        Cost times(int factor) const;
        Cost& operator +=(const Cost& other);
        bool operator <(const Cost& other) const;
        std::string text() const {return digits;
        }
    };
    struct Allocation {
        std::map<std::string, Variables> neighbors, partners;
        std::map<std::string, Cost> costs;
        std::vector<std::string> order;
        std::vector<std::pair<std::string, int>> potential;
        std::map<std::string, int> colors;
        Variables spills;
        Allocation(const Function& function, const CFG& graph, const DataFlow& flow, int registers);
    };
}
#endif

#include "tac.hpp"
namespace tac {
    const std::vector<std::string> kinds = {"copy", "bin", "load", "store", "goto", "if", "param", "call", "return", "read", "print"};
    Operand Operand::parse(const std::string& word) {
        Operand result;
        if (!word.empty() &&(word[0] == '-' ||(word[0] >= '0' && word[0] <= '9'))) {
            result.constant = true;
            result.number = std::stoll(word);
        } else result.variable = word;
        return result;
    }
    Operand Operand::value(Integer number) {
        Operand result;
        result.constant = true;
        result.number = number;
        return result;
    }
    std::string Operand::text() const {return constant ? std::to_string(number) : variable;
    } bool Operand::operator <(const Operand& other) const {return std::tie(constant, number, variable) < std::tie(other.constant, other.number, other.variable);
    } bool Operand::operator ==(const Operand& other) const {return constant == other.constant &&(constant ? number == other.number : variable == other.variable);
    } bool Expression::operator <(const Expression& other) const {return std::tie(kind, operation, a, b) < std::tie(other.kind, other.operation, other.a, other.b);
    } bool Expression::operator ==(const Expression& other) const {return kind == other.kind && operation == other.operation && a == other.a && b == other.b;
    } std::string Expression::text() const {return kind == "load" ? operation + "[" + a.text() + "]" : a.text() + operation + b.text();
    } bool Expression::uses(const std::string& v) const {return(!a.constant && a.variable == v) ||(kind == "bin" && !b.constant && b.variable == v);
    } std::vector<Operand*> Instruction::operands() {
        if (kind == "bin" || kind == "if" || kind == "store") return {&a, &b};
        if (kind == "copy" || kind == "load" || kind == "param" || kind == "print" ||(kind == "return" && has_operand)) return {&a};
        return {};
    }
    std::vector<Operand> Instruction::operands() const {Instruction copy = *this;
    std::vector<Operand> result;
    for (Operand* value : copy.operands()) result.push_back(*value);
    return result;
    } std::vector<std::string> Instruction::uses() const {std::vector<std::string> result;
    for (const Operand& value : operands()) if (!value.constant) result.push_back(value.variable);
    return result;
    } std::optional<Expression> Instruction::expression() const {if (kind == "bin") return Expression {kind, operation, a, b};
    if (kind == "load") return Expression {kind, name, a, {} };
    return std::nullopt;
    } std::string Instruction::text() const {if (kind == "copy") return destination + " = " + a.text();
    if (kind == "bin") return destination + " = " + a.text() + " " + operation + " " + b.text();
    if (kind == "load") return destination + " = " + name + "[" + a.text() + "]";
    if (kind == "store") return name + "[" + a.text() + "] = " + b.text();
    if (kind == "goto") return "goto " + name;
    if (kind == "if") return "if " + a.text() + " " + operation + " " + b.text() + " goto " + name;
    if (kind == "call") return(destination.empty() ? "" : destination + " = ") + "call " + name + " " + std::to_string(count);
    if (kind == "read") return "read " + destination;
    if (kind == "return" && !has_operand) return "return";
    return kind + " " + a.text();
    } int Function::instruction_count() const {return static_cast<int>(std::count_if(code.begin(), code.end(),[](const Line& line) {
        return !line.is_label();
    }));
    } static std::pair<std::string, Operand> array_operand(const std::string& word) {
        std::size_t bracket = word.find('[');
        return {word.substr(0, bracket), Operand::parse(word.substr(bracket + 1, word.size() - bracket - 2))};
    }
    static Instruction parse_instruction(const std::vector<std::string>& w) {
        Instruction s;
        const std::string& first = w[0];
        if (first == "goto") {
            s.kind = first;
            s.name = w[1];
        } else if (first == "if") {
            s.kind = first;
            s.a = Operand::parse(w[1]);
            s.operation = w[2];
            s.b = Operand::parse(w[3]);
            s.name = w[5];
        } else if (first == "param" || first == "print" || first == "return") {
            s.kind = first;
            s.has_operand = w.size() > 1;
            if (s.has_operand) s.a = Operand::parse(w[1]);
        } else if (first == "read") {
            s.kind = first;
            s.destination = w[1];
        } else if (first == "call") {
            s.kind = first;
            s.name = w[1];
            s.count = std::stoi(w[2]);
        } else if (first.find('[') != std::string::npos) {
            s.kind = "store";
            std::tie(s.name, s.a) = array_operand(first);
            s.b = Operand::parse(w[2]);
        } else {
            s.destination = first;
            if (w[2] == "call") {
                s.kind = "call";
                s.name = w[3];
                s.count = std::stoi(w[4]);
            } else if (w.size() == 5) {
                s.kind = "bin";
                s.a = Operand::parse(w[2]);
                s.operation = w[3];
                s.b = Operand::parse(w[4]);
            } else if (w[2].find('[') != std::string::npos) {
                s.kind = "load";
                std::tie(s.name, s.a) = array_operand(w[2]);
            } else {
                s.kind = "copy";
                s.a = Operand::parse(w[2]);
            }
        }
        return s;
    }
    Program read_program(const std::string& path) {
        Program result;
        std::ifstream input(path);
        std::string text;
        while (std::getline(input, text)) {
            std::istringstream stream(text);
            std::vector<std::string> words;
            std::string word;
            while (stream >> word) words.push_back(word);
            if (words.empty() || words[0][0] == '#') continue;
            if (words[0] == "array") result.arrays.emplace_back(words[1], std::stoi(words[2]));
            else if (words[0] == "func") {
                Function f;
                f.name = words[1];
                f.parameters.assign(words.begin() + 2, words.end());
                result.functions.push_back(f);
            } else if (words[0] == "end") continue;
            else if (words.size() == 1 && words[0].back() == ':') result.functions.back().code.push_back(Line::named(words[0].substr(0, words[0].size() - 1)));
            else result.functions.back().code.push_back(Line::code(parse_instruction(words)));
        }
        return result;
    }
    Integer calculate(const std::string& op, Integer a, Integer b) {
        if (op == "+") return a + b;
        if (op == "-") return a - b;
        if (op == "*") return a * b;
        if (op == "/") return a/b;
        if (op == "%") return a%b;
        if (op == "<") return a < b;
        if (op == "<=") return a <= b;
        if (op == ">") return a > b;
        if (op == ">=") return a >= b;
        if (op == "==") return a == b;
        return a != b;
    }
    std::string join(const std::vector<std::string>& values, const std::string& separator, const std::string& empty) {
        if (values.empty()) return empty;
        std::string result = values[0];
        for (std::size_t i = 1;i < values.size();++i) result += separator + values[i];
        return result;
    }
    std::string numbers(const std::vector<int>& values, const std::string& prefix) {
        std::vector<std::string> strings;
        for (int value : values) strings.push_back(prefix + std::to_string(value));
        return join(strings);
    }
    std::string numbers(const std::set<int>& values, const std::string& prefix) {
        return numbers(std::vector<int>(values.begin(), values.end()), prefix);
    }
    std::vector<std::string> function_lines(const Function& function) {
        std::vector<std::string> result;
        std::string first = "func " + function.name;
        for (const std::string& p : function.parameters) first += " " + p;
        result.push_back(first);
        for (const Line& line : function.code) result.push_back(line.is_label() ? line.label + ":" : "    " + line.instruction.text());
        result.push_back("end");
        return result;
    }
    std::vector<std::string> program_lines(const Program& program) {
        std::vector<std::string> result;
        for (const std::pair<std::string, int>& a : program.arrays) result.push_back("array " + a.first + " " + std::to_string(a.second));
        for (const Function& f : program.functions) {
            if (!result.empty()) result.push_back("");
            std::vector<std::string> lines = function_lines(f);
            result.insert(result.end(), lines.begin(), lines.end());
        }
        return result;
    }
}
